import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        int row = 0, column = 0;
        for (int k = 0; k < m; k++) {
            String command = next();
            int nr = row, nc = column;
            switch (command) {
                case "UP" -> nr--;
                case "DOWN" -> nr++;
                case "LEFT" -> nc--;
                default -> nc++;
            }
            // Moves that would leave the grid are ignored.
            if (0 <= nr && nr < n && 0 <= nc && nc < n) {
                row = nr;
                column = nc;
            }
        }
        System.out.println(row * n + column);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	row, column := 0, 0
	for k := 0; k < m; k++ {
		nr, nc := row, column
		switch nextToken() {
		case "UP":
			nr--
		case "DOWN":
			nr++
		case "LEFT":
			nc--
		default:
			nc++
		}
		// Moves that would leave the grid are ignored.
		if 0 <= nr && nr < n && 0 <= nc && nc < n {
			row, column = nr, nc
		}
	}
	fmt.Println(row*n + column)
}
